-- ============================================================
-- /integrations/ai becomes CMS-managed, like /integrations/google-sheets.
--
-- integration_pages gains a `content` jsonb column for page-specific
-- sections that don't fit the generic columns (examples, connect cards,
-- safeguards, data cards, support block). Existing rows get '{}'.
--
-- The 'ai' row is seeded with the page's original copy. ON CONFLICT DO
-- NOTHING: re-running never overwrites what a super admin has edited.
-- ============================================================

ALTER TABLE public.integration_pages
  ADD COLUMN IF NOT EXISTS content jsonb NOT NULL DEFAULT '{}'::jsonb;

INSERT INTO public.integration_pages (
  slug, title, subtitle, badge_text,
  primary_cta_text, primary_cta_url, secondary_cta_text, secondary_cta_url,
  prerequisites, features, how_it_works, faqs,
  privacy_markdown, terms_markdown, seo_meta_title, seo_meta_description,
  is_published, content
) VALUES (
  'ai', 'Replai for Claude and ChatGPT', 'Connect Claude or ChatGPT to your Replai WhatsApp CRM. Ask about your inbox, contacts and deals, update records, and send WhatsApp messages — with your own permissions and the limits your workspace sets.', 'AI connector',
  'Add to Claude', '', 'Add to ChatGPT', '',
  '["Sign in with your Replai account","You choose what it may do","Disconnect any time"]'::jsonb,
  '[{"icon":"Eye","title":"View","description":"Contacts, tags, notes, inbox conversations and messages, deals, templates, broadcast results, automations and dashboard numbers."},{"icon":"PencilLine","title":"Edit records","description":"Create and update contacts, tags, notes and custom fields; change conversation status and assignment; create and move deals."},{"icon":"Send","title":"Send messages","description":"Send WhatsApp messages and approved templates as you. Free text only inside WhatsApp’s 24-hour reply window."},{"icon":"Users","title":"Broadcasts","description":"Send a template to many contacts. Always shown as a preview first, and only sent after you confirm it."},{"icon":"Zap","title":"Automations on/off","description":"Switch existing automations and flows on or off. Their steps can’t be edited from the AI app."}]'::jsonb,
  '[]'::jsonb,
  '[{"question":"Do I need a Replai account?","answer":"Yes. You sign in to Replai when you connect, and the AI app only ever sees the workspace you signed in to."},{"question":"What data does the AI app receive?","answer":"Only what its tool calls return while you use it — for example the contact, conversation or deal you asked about. That data is then processed by Anthropic (Claude) or OpenAI (ChatGPT) under their terms. Replai does not receive your chat with the AI app."},{"question":"What does Replai store about the connection?","answer":"The connection itself (which app, which permissions, when it was last used), hashed access tokens, and an activity log of each action with ids and counts but not message text. Activity is kept for 90 days."},{"question":"How do I disconnect?","answer":"In Replai, open Settings → AI Connectors and select Disconnect on the connection. You can also ask the AI app to disconnect, or remove the connector in Claude or ChatGPT. Unused connections disconnect themselves after 30 days by default."},{"question":"Can my team members connect too?","answer":"If the workspace owner allows it. Each person connects their own AI app and it works with that person’s permissions. The owner sees every connection in the workspace and can disconnect any of them."}]'::jsonb,
  '', '', 'Replai for Claude and ChatGPT', 'Connect Claude or ChatGPT to your Replai WhatsApp CRM: look up contacts and conversations, update records and send WhatsApp messages with your own permissions.',
  true,
  '{"examples_heading":"What you can ask","examples_subtitle":"Write in your own words. The AI app picks the right Replai action and shows you what it did.","examples":["How many open conversations do I have, and which are unread?","What did Ravi last say to us?","Add a note on Ravi: called, wants a demo on Friday.","Move Ravi’s deal to Won.","Reply to Ravi: “Thanks, sending the invoice now.”","Send the order_invoice_pdf template to Ravi for order ORD-5074.","How did yesterday’s broadcast perform?"],"connect_heading":"How to connect","connect_subtitle":"You need a Replai account. When you connect, Replai opens in your browser so you can sign in and choose the permissions.","connect_cards":[{"title":"Claude","steps":["In Claude, open Settings → Connectors.","Find Replai in the directory, or choose Add custom connector and enter the server URL below.","Select Connect, sign in to Replai and approve."]},{"title":"ChatGPT","steps":["In ChatGPT, open the plugin directory and search for Replai.","Select Connect, sign in to Replai and approve.","Before Replai is listed, you can add it with developer mode using the server URL below."]}],"server_url_label":"Server URL:","server_url_note":"Claude Code and Codex use the same URL.","permissions_heading":"What it may do","permissions_subtitle":"Viewing is always included. Each other level is a separate choice when you connect, and a switch you can turn off later.","safeguards_heading":"Safeguards","safeguards":["The AI app acts as you, with your Replai role and permissions — never more.","You choose what it may do when you connect, and can narrow it any time in Settings → AI Connectors.","The workspace owner sets a policy for the whole workspace: which apps are allowed, whether members may connect, and whether sending, broadcasts and automation changes are allowed at all.","Daily limits on messages and broadcast recipients (by default 100 messages per connection, 300 per workspace and 500 broadcast recipients per workspace).","Broadcasts, and tag changes on more than 25 contacts, always need a preview and your confirmation. The owner can require a preview for every message.","Messages sent this way are marked “via Claude” or “via ChatGPT” in the inbox, and every action is listed under Recent activity.","Customers who opted out of marketing are skipped for marketing templates. The AI app can’t change the opt-out list.","It can’t delete contacts or conversations, read API keys or WhatsApp credentials, change billing, or manage team members."],"data_heading":"Your data","data_cards":[{"title":"Sign-in","body":"Standard OAuth 2.1 sign-in. The AI app never sees your Replai password; it gets a token that only works for this connection.","icon":"KeyRound"},{"title":"What leaves Replai","body":"Only what the AI app’s actions return while you use it. It is then processed by Anthropic or OpenAI under their terms.","icon":"Lock"},{"title":"What Replai keeps","body":"The connection, hashed tokens, and an activity log (ids and counts, not message text) for 90 days.","icon":"ListChecks"}],"faq_heading":"Questions","support_heading":"Need help?","support_body":"Questions about connecting, permissions or your data — we’re happy to help.","support_cta_text":"Contact support","support_cta_url":"/contact","manage_cta_text":"Manage connections","manage_cta_url":"/settings?tab=ai-connectors","trademark_note":"Claude is a trademark of Anthropic, PBC. ChatGPT is a trademark of OpenAI. WhatsApp is a trademark of Meta Platforms, Inc. Replai is not made or endorsed by Anthropic or OpenAI."}'::jsonb
)
ON CONFLICT (slug) DO NOTHING;
